for relative, payload in FILES.items():
    target = Path(relative)
    target.parent.mkdir(parents=True, exist_ok=True)
    target.write_bytes(zlib.decompress(base64.b85decode(payload.encode("ascii"))))

part1 = Path("scripts/.v220-js-part1.txt")
part2 = Path("scripts/.v220-js-part2.txt")
payload = part1.read_text(encoding="ascii") + part2.read_text(encoding="ascii")
target = Path("provider-assessment-demo/institutional-contract-v220.js")
target.parent.mkdir(parents=True, exist_ok=True)
